CREATE TABLE IF NOT EXISTS kx_family_config (id TEXT PRIMARY KEY DEFAULT 'main', cfg JSONB NOT NULL DEFAULT '{"on":false,"min":15,"bonus":0,"lock":"","reset_seq":0}'::jsonb, updated_at TIMESTAMPTZ NOT NULL DEFAULT now()); CREATE TABLE IF NOT EXISTS kx_usage_daily (day TEXT NOT NULL, module TEXT NOT NULL, device TEXT NOT NULL, sec INTEGER NOT NULL DEFAULT 0, updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY (day, module, device)); CREATE INDEX IF NOT EXISTS kx_usage_day_idx ON kx_usage_daily(day);
